import java.util.Scanner;

class Barang {
    String nama;
    int harga;
    int jumlah;

    Barang(String nama, int harga, int jumlah) {
        this.nama = nama;
        this.harga = harga;
        this.jumlah = jumlah;
    }

    int total() {
        return harga * jumlah;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        String nama = in.nextLine();
        int harga = Integer.parseInt(in.nextLine().trim());
        int jumlah = Integer.parseInt(in.nextLine().trim());
        Barang b = new Barang(nama, harga, jumlah);
        System.out.println("Barang: " + b.nama);
        System.out.println("Harga: Rp " + b.harga);
        System.out.println("Jumlah: " + b.jumlah);
        System.out.println("Total: Rp " + b.total());
    }
}

