import java.util.Scanner;

class Dompet {
    private int saldo;

    int getSaldo() {
        return saldo;
    }

    boolean isi(int jumlah) {
        if (jumlah <= 0) {
            return false;
        }
        saldo += jumlah;
        return true;
    }

    boolean tarik(int jumlah) {
        if (jumlah <= 0 || jumlah > saldo) {
            return false;
        }
        saldo -= jumlah;
        return true;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        Dompet d = new Dompet();
        while (in.hasNextLine()) {
            String[] p = in.nextLine().trim().split(" ");
            if (p[0].equals("SELESAI")) {
                break;
            }
            int n = Integer.parseInt(p[1]);
            boolean ok = p[0].equals("ISI") ? d.isi(n) : d.tarik(n);
            if (ok) {
                System.out.println("Saldo: " + d.getSaldo());
            } else {
                System.out.println("Ditolak");
            }
        }
        System.out.println("Saldo akhir: " + d.getSaldo());
    }
}
